use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclenum! {
# [doc = " Current state of a blocking task."] enum State < T > { # [doc = " There is no blocking task."] # [doc = ""] # [doc = " The inner value is readily available, unless it has already been extracted. The value is"] # [doc = " extracted out by [`Unblock::into_inner()`], [`AsyncWrite::poll_close()`], or by awaiting"] # [doc = " [`Unblock`]."] Idle (Option < Box < T > >) , # [doc = " A [`Unblock::with_mut()`] closure was spawned and is still running."] WithMut (Task < Box < T > >) , # [doc = " The inner value is an [`Iterator`] currently iterating in a task."] # [doc = ""] # [doc = " The `dyn Any` value here is a `Pin<Box<Receiver<<T as Iterator>::Item>>>`."] Streaming (Option < Box < dyn Any + Send + Sync > > , Task < Box < T > >) , # [doc = " The inner value is a [`Read`] currently reading in a task."] Reading (Option < Reader > , Task < (io :: Result < () > , Box < T >) >) , # [doc = " The inner value is a [`Write`] currently writing in a task."] Writing (Option < Writer > , Task < (io :: Result < () > , Box < T >) >) , # [doc = " The inner value is a [`Seek`] currently seeking in a task."] Seeking (Task < (SeekFrom , io :: Result < u64 > , Box < T >) >) , }
}